mapper.select:
SELECT fd.id, fdd.id as detailId, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime, fdd.platform_sku_no as thirdWarehouseSku, fd.logistics_status, fdd.fba_shipment_code fbaShipmentCode, pt.packing_status as packingStatus, pt.id as taskId, fd.declare_status FROM first_mile_delivery_detail fdd LEFT JOIN first_mile_delivery fd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN packing_task pt on (pt.source_id = fd.id or pt.source_id = fd.source_id ) and pt.is_deleted = false WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fd.id, fd.code, fd.source_code AS sourceCode, fd.demand_type AS demandType, fd.approve_status AS approveStatus, fd.invalid_status AS invalidStatus, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.country_id AS countryId, fd.country_name AS countryName, fd.delivery_warehouse_id AS deliveryWarehouseId, fd.delivery_warehouse_name AS deliveryWarehouseName, fd.dest_warehouse_id AS destWarehouseId, fd.dest_warehouse_name AS destWarehouseName, fdd.platform_spu_no AS platformSpuNo, fdd.platform_sku_no AS platformSkuNo, fdd.fn_sku AS fnSku, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty, fdd.is_combination AS isCombination, fd.remark AS remark, fd.create_user_name AS createUserName, fd.create_time AS createTime, fd.approve_user_name AS approveUserName, fd.approve_time AS approveTime, op.code as provideCode, fdd.platform_sku_no as thirdWarehouseSku, fd.logistics_status, fd.declare_status, fdd.fba_shipment_code fbaShipmentCode FROM first_mile_delivery fd INNER JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN overseas_provider_warehouse opw on opw.warehouse_id = fd.dest_warehouse_id and opw.is_deleted = false LEFT JOIN overseas_provider op on op.id = opw.main_id and op.is_deleted = false WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fd.code AS deliveryCode, CASE WHEN approve_status = 'approve' THEN '已发货' ELSE '未发货' END AS deliveryStatus, CASE WHEN approve_status = 'approve' THEN '已发货' ELSE '未发货' END AS deliveryStatusName, SUM(fdd.delivery_qty) AS deliveryQty, fd.approve_time AS deliveryTime, CASE WHEN fd.demand_type = 'demandPlatformWarehouse' THEN (select fdd2.fba_shipment_code from first_mile_delivery_detail fdd2 where fdd2.main_id = fd.id and fdd2.is_deleted = false limit 1) ELSE(SELECT owi.code from overseas_warehouse_inbound owi where owi.is_deleted = false and owi.source_code = fd.code limit 1 ) END as refCode FROM first_mile_delivery fd INNER JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE WHERE fd.is_deleted = FALSE
AND fd.source_id IN
#{sourceId}
AND fdd.fba_shipment_code = #{fbaShipmentCode}
GROUP BY fd.code, deliveryStatus, fd.approve_time, fd.id, fd.demand_type ORDER BY fd.code DESC

SELECT  EXTRACT(year FROM md.approve_time),  EXTRACT(month FROM md.approve_time) as month,
        count(1)
from first_mile_delivery md
where md.is_deleted = false
  and md.declare_status != 'none'

    and  md.approve_status = #{status}


    and md.approve_time >= #{beginDate}


    and md.approve_time <=  #{endDate}



    ${permissionSql}

group by EXTRACT(month FROM md.approve_time), EXTRACT(year FROM md.approve_time)
order by  EXTRACT(year FROM md.approve_time), EXTRACT(month FROM md.approve_time)

select fmd.id as sourceId, fmd.code as sourceCode, fmd.country_id as country, fmd.country_name as countryName, fmd.source_type as businessType from first_mile_delivery fmd inner join packing_task pt on pt.source_id = fmd.id and pt.is_deleted = false where fmd.is_deleted = false
AND (pt.packing_status = #{params.packingStatus} or fmd.approve_status = 'approve')
AND fmd.declare_status = #{params.declareStatus}
AND fmd.id IN
#{id}

SELECT fd.id as sourceId, fdd.id as sourceDetailId, fd.code as sourceCode, 'delivery' as sourceType, concat(fdd.fba_shipment_code,owi.code) AS businessCode, fdd.fba_shipment_code as fbaShipmentCode, owi.code as overseasWarehouseCode, fd.demand_type AS businessType, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.delivery_warehouse_id AS warehouseId, fd.delivery_warehouse_name AS warehouseName, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.platform_sku_no AS platformSkuNo, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty FROM first_mile_delivery_detail fdd LEFT JOIN first_mile_delivery fd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN overseas_warehouse_inbound owi ON owi.source_id = fd.id AND owi.is_deleted = FALSE and owi.instock_status != 'canceled' WHERE ${params.sqlMap.default} and fd.is_deleted = FALSE and fd.approve_status = 'approve'
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fd.create_time DESC, fd.code, fdd.id

SELECT fd.id as sourceId, fdd.id as sourceDetailId, fd.code as sourceCode, 'delivery' as sourceType, concat(fdd.fba_shipment_code,owi.code) AS businessCode, fdd.fba_shipment_code as fbaShipmentCode, owi.code as overseasWarehouseCode, fd.demand_type AS businessType, fd.shop_id AS shopId, fd.shop_name AS shopName, fd.delivery_warehouse_id AS warehouseId, fd.delivery_warehouse_name AS warehouseName, fdd.sku_id AS skuId, fdd.sku_no AS skuNo, fdd.platform_sku_no AS platformSkuNo, fdd.product_name AS productName, fdd.stock_sku AS stockSku, fdd.plan_qty AS planQty, fdd.delivery_qty AS deliveryQty FROM first_mile_delivery_detail fdd LEFT JOIN first_mile_delivery fd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE LEFT JOIN overseas_warehouse_inbound owi ON owi.source_id = fd.id AND owi.is_deleted = FALSE and owi.instock_status != 'canceled' WHERE fd.is_deleted = FALSE and fd.approve_status = 'approve'
and fd.code in
#{item}
and concat(fdd.fba_shipment_code,owi.code) in
#{item}
GROUP BY sourceId,sourceDetailId,sourceCode,sourceType,businessCode,overseasWarehouseCode,fbaShipmentCode,businessType,shopId,shopName,warehouseId,warehouseName,skuId,skuNo,platformSkuNo,stockSku,planQty,deliveryQty

SELECT fd.id, fd.code, fdd.id as detailId, concat(fdd.fba_shipment_code,owi.code) AS businessCode, fdd.fba_shipment_code as fbaShipmentCode, owi.code as overseasWarehouseCode FROM first_mile_delivery fd LEFT JOIN first_mile_delivery_detail fdd ON fdd.main_id = fd.id AND fdd.is_deleted = FALSE LEFT JOIN overseas_warehouse_inbound owi ON owi.source_id = fd.id AND owi.is_deleted = FALSE and owi.instock_status != 'canceled' where fd.is_deleted = FALSE
and fd.id in
#{item}

SELECT fd.id, fd.code, fdd.id as detailId, concat(fdd.fba_shipment_code,owi.code) AS businessCode, fdd.fba_shipment_code as fbaShipmentCode, owi.code as overseasWarehouseCode FROM first_mile_delivery fd LEFT JOIN first_mile_delivery_detail fdd ON fdd.main_id = fd.id AND fdd.is_deleted = FALSE LEFT JOIN overseas_warehouse_inbound owi ON owi.source_id = fd.id AND owi.is_deleted = FALSE and owi.instock_status != 'canceled' where fd.is_deleted = FALSE
and fd.code in
#{item}

SELECT distinct fmd.id as firstMileId, wc.id, wc.packing_task_id as taskId, (select fsp.box_no from fba_shipment_packing fsp where fsp.carton_id = wc.id and fsp.is_deleted = false limit 1 ) as fbaBoxNo, wc.box_no, concat(wcs.box_length, wcs.size_unit,'*', wcs.box_width, wcs.size_unit,'*', wcs.box_height,wcs.size_unit) AS boxSize, wcs.package_weight, wcs.weight_unit, wc.weighting_status, wc.packing_status, wc.packing_user_name, wcs.measure_source, wc.error_msg, pt.source_id , wcs.box_length as length, wcs.box_width as width, wcs.box_height as height, wcd.sku_id, wcd.sku_no, wcd.pack_qty, concat(wcd.sku_no,'*',wcd.pack_qty) AS sku, fmd.code as deliveryCode, case when fmd.demand_type = 'demandPlatformWarehouse' then (SELECT fba_shipment_code from first_mile_delivery_detail fmdd where fmdd.main_id = fmd.id and fmdd.is_deleted = false limit 1 ) else (SELECT code from overseas_warehouse_inbound owi where owi.source_id = fmd.id and owi.is_deleted = false limit 1) end as businessCode, fmdd.platform_sku_no||'*'||wcd.pack_qty as platformSku, fmdd.fn_sku||'*'||wcd.pack_qty as fnSku from first_mile_delivery fmd inner join first_mile_delivery_detail fmdd on fmd.id = fmdd.main_id and fmdd.is_deleted = false inner join packing_task pt on (pt.source_id = fmd.id or pt.source_id = fmd.source_id) and pt.is_deleted = false inner join wms_carton wc on wc.packing_task_id = pt.id and wc.is_deleted =false INNER JOIN wms_carton_spec wcs ON wc.spec_id = wcs.id and wcs.is_deleted = FALSE INNER JOIN wms_carton_detail wcd ON wc.id = wcd.main_id and wcd.is_deleted = FALSE and wcd.sku_id = fmdd.sku_id where ${params.sqlMap.default} and fmd.is_deleted = false AND wcd.pack_qty > 0
AND fmd.id IN
#{id}
${permissionSql}
ORDER BY fmd.code
